INSERT INTO `blogs` (`id`, `blog_category_id`, `title`, `title_ar`, `slug`, `description`, `description_ar`, `view`, `image`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'Who are we', 'Who are we', 'who-are-we', '<span style=\"color: rgb(66, 66, 66); font-family: Inter, sans-serif; letter-spacing: normal;\">Amlaek is a leading platform specialized in marketing income-generating commercial properties, and for all the services you need at the highest international standards.</span>', '<span style=\"color: rgb(66, 66, 66); font-family: Inter, sans-serif; letter-spacing: normal;\">تنمية الأملاك هي منصة رائدة متخصصة في تسويق الاملاك التجارية المدرة للدخل , ولكل ما تحتاج إليه من خدمات بأعلى المعايير الدولية</span>', 74, '67c9db4e189841741282126.png', 'active', '2024-04-05 22:32:38', '2025-06-22 05:33:58');
INSERT INTO `blogs` (`id`, `blog_category_id`, `title`, `title_ar`, `slug`, `description`, `description_ar`, `view`, `image`, `status`, `created_at`, `updated_at`) VALUES
(2, 1, 'Kingdom of Saudi Property show Luxury Events 3', 'Kingdom of Saudi Property show Luxury Events 3', 'kingdom-of-saudi-property-show-luxury-events-3', '<span style=\"font-family: Inter, sans-serif; letter-spacing: normal; white-space-collapse: preserve; background-color: rgb(245, 251, 255);\">The Minister of Municipal, Rural Affairs and Housing, Chairman of the Board of Directors of the Real Estate Authority, Majid bin Abdullah Al-Hogail, inaugurates the second edition of the Second Maskan Real Estate Exhibition 2024. It is sponsored by the Ministry of Municipal, Rural Affairs and Housing and the General Real Estate Authority, and with the participation of a number of government agencies, banks, finance and real estate development companies.<br>The exhibition aims to provide a complete journey for the beneficiary to own his home by facilitating communication with developers and financing agencies and providing them with the necessary consultations. It also includes holding workshops and launching real estate investment funds. It also presented the most important real estate projects for developers, financing</span><span data-metadata=\"<!--(figmeta)eyJmaWxlS2V5IjoiR2pFVlkyQjVyR0VqRlNpQmRkQVJ4dyIsInBhc3RlSUQiOjMzMjI1Nzk4MiwiZGF0YVR5cGUiOiJzY2VuZSJ9Cg==(/figmeta)-->\" style=\"font-family: Inter, sans-serif; letter-spacing: normal; background-color: rgb(245, 251, 255);\"></span><span data-buffer=\"<!--(figma)(/figma)-->\" style=\"font-family: Inter, sans-serif; letter-spacing: normal; background-color: rgb(245, 251, 255);\"></span><span style=\"font-family: Inter, sans-serif; letter-spacing: normal; white-space-collapse: preserve; background-color: rgb(245, 251, 255);\">The Minister of Municipal, Rural Affairs and Housing, Chairman of the Board of Directors of the Real Estate Authority, Majid bin Abdullah Al-Hogail, inaugurates the second edition of the Second Maskan Real Estate Exhibition 2024. It is sponsored by the Ministry of Municipal, Rural Affairs and Housing and the General Real Estate Authority, and with the participation of a number of government agencies, banks, finance and real estate development companies.<br>The exhibition aims to provide a complete journey for the beneficiary to own his home by facilitating communication with developers and financing agencies and providing them with the necessary consultations. It also includes holding workshops and launching real estate investment funds. It also presented the most important real estate projects for developers, financing&nbsp;</span><br>', '<div style=\"color: rgb(0, 0, 0); font-family: Inter, sans-serif; letter-spacing: normal; background-color: rgb(245, 251, 255);\">افتتح وزير الشؤون البلدية والقروية والإسكان رئيس مجلس إدارة المؤسسة العقارية ماجد بن عبدالله الحقيل النسخة الثانية من معرض مسكن العقاري الثاني 2024 برعاية وزارة البلدية وشئون الريف والإسكان والهيئة العامة العقارية، وبمشاركة عدد من الجهات الحكومية والبنوك وشركات التمويل والتطوير العقاري.</div><div style=\"color: rgb(0, 0, 0); font-family: Inter, sans-serif; letter-spacing: normal; background-color: rgb(245, 251, 255);\">ويهدف المعرض إلى تقديم رحلة كاملة للمستفيد لامتلاك منزله من خلال تسهيل التواصل مع المطورين وجهات التمويل وتقديم الاستشارات اللازمة لهم. كما يتضمن عقد ورش عمل وإطلاق صناديق الاستثمار العقاري. كما عرضت أهم المشاريع العقارية للمطورين والتمويل وزير الشؤون البلدية والقروية والإسكان رئيس مجلس إدارة المؤسسة العقارية ماجد بن عبدالله الحقيل يفتتح النسخة الثانية من معرض مسكن العقاري الثاني المعرض العقاري 2024. يقام برعاية وزارة الشؤون البلدية والقروية والإسكان والهيئة العامة العقارية، وبمشاركة عدد من الجهات الحكومية والبنوك وشركات التمويل والتطوير العقاري.</div><div style=\"color: rgb(0, 0, 0); font-family: Inter, sans-serif; letter-spacing: normal; background-color: rgb(245, 251, 255);\">ويهدف المعرض إلى تقديم رحلة كاملة للمستفيد لامتلاك منزله من خلال تسهيل التواصل مع المطورين وجهات التمويل وتقديم الاستشارات اللازمة لهم. كما يتضمن عقد ورش عمل وإطلاق صناديق الاستثمار العقاري. كما عرضت أهم المشاريع العقارية للمطورين والتمويل</div>', 20, '67c9db397bd2a1741282105.png', 'active', '2024-05-22 10:36:18', '2025-06-22 05:43:32');
INSERT INTO `blogs` (`id`, `blog_category_id`, `title`, `title_ar`, `slug`, `description`, `description_ar`, `view`, `image`, `status`, `created_at`, `updated_at`) VALUES
(3, 1, 'Who are we 2', 'Who are we 2', 'who-are-we-2', '<span style=\"color: rgb(66, 66, 66); font-family: Inter, sans-serif; letter-spacing: normal;\">Amlaek is a leading platform specialized in marketing income-generating commercial properties, and for all the services you need at the highest international standards.</span>', '<span style=\"color: rgb(66, 66, 66); font-family: Inter, sans-serif; letter-spacing: normal;\">تنمية الأملاك هي منصة رائدة متخصصة في تسويق الاملاك التجارية المدرة للدخل , ولكل ما تحتاج إليه من خدمات بأعلى المعايير الدولية</span>', 81, '67c9db1c3ecb81741282076.png', 'active', '2024-04-05 22:32:38', '2025-06-22 05:43:40');
