(292, 'labsincu.element', '{\"title\":\"The team\\u2019s diverse experiences in various business fields and sectors, such as contracting, trade, education, consulting, hospitality, and others\",\"title_ar\":\"\\u062a\\u0646\\u0648\\u0639 \\u062e\\u0628\\u0631\\u0627\\u062a \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0641\\u064a \\u0645\\u062c\\u0627\\u0644\\u0627\\u062a \\u0648 \\u0642\\u0637\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0644\\u0641\\u0629 \\u0643\\u0627\\u0644\\u0645\\u0642\\u0627\\u0648\\u0644\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0629\\u060c \\u0648\\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0648\\u0627\\u0644\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0636\\u064a\\u0627\\u0641\\u0629 \\u0648\\u063a\\u064a\\u0631\\u0647\\u0627 \\u0647\\u0630\\u0627 \\u0645\\u0645\\u0627\"}', NULL, '2025-02-20 11:46:20', '2025-02-26 16:23:53'),
(293, 'authentication_of_documents.content', '{\"title\":\"Authentication of documents\",\"title_ar\":\"\\u062a\\u0635\\u062f\\u064a\\u0642 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a\"}', NULL, '2025-02-20 11:47:47', '2025-02-26 16:26:09'),
(294, 'authentication_of_documents.element', '{\"title\":\"Authentication of documents for a large number of countries. We handle the attestation of educational certificates, personal documents, marriage and adoption, as well as police documents such as criminal records checks, data disclosure documents, etc. Contact us today to process all the documents you need.\",\"title_ar\":\"\\u062a\\u0635\\u062f\\u064a\\u0642 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0644\\u0639\\u062f\\u062f\\u064d \\u0643\\u0628\\u064a\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0644\\u062f\\u0627\\u0646. \\u0646\\u062d\\u0646 \\u0646\\u062a\\u0648\\u0644\\u0651\\u064e\\u0649 \\u0639\\u0646\\u0643 \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u062a\\u0635\\u062f\\u064a\\u0642 \\u0627\\u0644\\u0634\\u064e\\u0651\\u0647\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u062a\\u0651\\u064e\\u0639\\u0644\\u064a\\u0645\\u064a\\u064e\\u0651\\u0629 \\u0648\\u0627\\u0644\\u0648\\u062b\\u0627\\u0626\\u0642 \\u0627\\u0644\\u0634\\u0651\\u064e\\u062e\\u0635\\u064a\\u0651\\u064e\\u0629 \\u0648\\u0627\\u0644\\u0632\\u0651\\u064e\\u0648\\u0627\\u062c \\u0648\\u0627\\u0644\\u062a\\u0651\\u064e\\u0628\\u0646\\u0651\\u0650\\u064a\\u060c \\u0641\\u0636\\u0644\\u064b\\u0627 \\u0639\\u0646 \\u0648\\u062b\\u0627\\u0626\\u0642 \\u0627\\u0644\\u0634\\u0651\\u064f\\u0631\\u0637\\u0629 \\u0643\\u0641\\u062d\\u0635 \\u0627\\u0644\\u0633\\u0651\\u0650\\u062c\\u0644\\u0651\\u064e\\u0627\\u062a \\u0627\\u0644\\u062c\\u0646\\u0627\\u0626\\u064a\\u0651\\u064e\\u0629 \\u0648\\u0648\\u062b\\u0627\\u0626\\u0642 \\u0627\\u0644\\u0625\\u0641\\u0635\\u0627\\u062d \\u0639\\u0646 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0648\\u063a\\u064a\\u0631\\u0647\\u0627 \\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0627\\u0644\\u064a\\u0648\\u0645 \\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0643\\u0644\\u0651 \\u0645\\u0627 \\u062a\\u062d\\u062a\\u0627\\u062c\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0648\\u0627\\u0644\\u0648\\u062b\\u0627\\u0626\\u0642\"}', NULL, '2025-02-20 11:47:59', '2025-02-26 16:26:49'),
(295, 'authentication_of_documents.element', '{\"title\":\"The suffering of obtaining a visa is a thing of the past\",\"title_ar\":\"\\u0645\\u0639\\u0627\\u0646\\u0627\\u0629 \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u0623\\u0634\\u064a\\u0631\\u0629 \\u0628\\u0627\\u062a\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0627\\u0636\\u064a\"}', NULL, '2025-02-20 11:48:10', '2025-02-26 16:28:49'),
(296, 'writing_cvs.content', '{\"title\":\"Writing CVs\",\"title_ar\":\"\\u0643\\u062a\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u064a\\u0631 \\u0627\\u0644\\u0630\\u0627\\u062a\\u064a\\u0629\",\"description\":\"Develop immediate plans related to writing CVs efficiently\",\"description_ar\":\"\\u0648\\u0636\\u0639 \\u0627\\u0644\\u062e\\u0637\\u0637 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a\\u0651\\u0629 \\u0627\\u0644\\u0645\\u064f\\u062a\\u0639\\u0644\\u0651\\u0650\\u0642\\u0629 \\u0628\\u0643\\u062a\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0633\\u064a\\u0631 \\u0627\\u0644\\u0630\\u0627\\u062a\\u064a\\u0629   \\u0628\\u0643\\u0641\\u0627\\u0621\\u0629\"}', NULL, '2025-02-20 11:49:34', '2025-02-26 16:31:18'),
(297, 'writing_cvs.element', '{\"title\":\"For our customers and partners around the world, we are not satisfied with...\",\"title_ar\":\"\\u0644\\u0639\\u0645\\u0644\\u0627\\u0626\\u0646\\u0627 \\u0648\\u0634\\u0631\\u0643\\u0627\\u0626\\u0646\\u0627 \\u062d\\u0648\\u0644 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u060c \\u0625\\u0630 \\u0644\\u0627 \\u0646\\u0643\\u062a\\u0641\\u064a \\u0628\"}', NULL, '2025-02-20 11:49:45', '2025-02-26 16:31:49'),
(298, 'writing_cvs.element', '{\"title\":\"Not only do we search for and hire candidates, but we also take it upon ourselves to provide a helping hand Our partners abroad own a medical center for labor diagnosis, and this is one of the group\\u2019s sectors. The vision of Gobinco Diagnostics was to provide accurate, high-quality medical diagnosis and laboratory examination.\",\"title_ar\":\"\\u0627\\u0644\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0631\\u0634\\u0651\\u062d\\u064a\\u0646 \\u0648\\u062a\\u0648\\u0638\\u064a\\u0641\\u0647\\u0645 \\u0648\\u062d\\u0633\\u0628\\u060c \\u0628\\u0644 \\u0646\\u0623\\u062e\\u0630 \\u0639\\u0644\\u0649 \\u0639\\u0627\\u062a\\u0642\\u0646\\u0627 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u064a\\u062f \\u0627\\u0644\\u0639\\u0648\\u0646  \\u064a\\u0645\\u062a\\u0644\\u0643 \\u0634\\u0631\\u0643\\u0627\\u0626\\u0646\\u0627 \\u0641\\u064a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c \\u0645\\u0631\\u0643\\u0632 \\u0637\\u0628\\u064a \\u0644\\u062a\\u0634\\u062e\\u064a\\u0635 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629 \\u0648\\u062a\\u0644\\u0643 \\u0625\\u062d\\u062f\\u0649 \\u0642\\u0637\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u062c\\u0645\\u0648\\u0639\\u0629\\u060c \\u0623\\u0646 \\u0631\\u0624\\u064a\\u0629 \\u062c\\u0648\\u0628\\u0646\\u0643\\u0648 \\u0644\\u0644\\u062a\\u0634\\u062e\\u064a\\u0635 \\u0643\\u0627\\u0646\\u062a \\u0627\\u0646\\u0637\\u0644\\u0627\\u0642\\u0627 \\u0644\\u062a\\u0648\\u0641\\u064a\\u0631 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0637\\u0628\\u064a \\u0648\\u0641\\u062d\\u0635 \\u0645\\u062e\\u062a\\u0628\\u0631\\u064a \\u062f\\u0642\\u064a\\u0642 \\u0648\\u0639\\u0627\\u0644\\u064a \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629\"}', NULL, '2025-02-20 11:49:56', '2025-02-26 16:34:39'),
(299, 'writing_cvs_documents.content', '{\"description\":\"Jobincu consists of a system of local, regional and international partnerships between recruitment agencies, global offices and logistics business sectors. It has strategic international relations based on trust with customers, and the role is:\",\"description_ar\":\"\\u062c\\u0648\\u0628\\u0646\\u0643\\u0648 \\u062a\\u062a\\u0643\\u0648\\u0646 \\u0645\\u0646 \\u0645\\u0646\\u0638\\u0648\\u0645\\u0629 \\u0634\\u0631\\u0627\\u0643\\u0627\\u062a \\u0645\\u062d\\u0644\\u064a\\u0629 \\u0648\\u0625\\u0642\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0648\\u062f\\u0648\\u0644\\u064a\\u0629 \\u0628\\u064a\\u0646 \\u0648\\u0643\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0648\\u0638\\u064a\\u0641 \\u0648\\u0627\\u0644\\u0645\\u0643\\u0627\\u062a\\u0628 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0648\\u0642\\u0637\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0644\\u0648\\u062c\\u0633\\u062a\\u064a\\u0629 .. \\u062a\\u0645\\u062a\\u0644\\u0643 \\u0639\\u0644\\u0627\\u0642\\u0627\\u062a \\u062f\\u0648\\u0644\\u064a\\u0629 \\u0627\\u0650\\u0633\\u062a\\u0631\\u0627\\u062a\\u064a\\u062c\\u064a\\u0651\\u064e\\u0629 \\u0639\\u0646\\u0648\\u0627\\u0646\\u0647\\u0627 \\u0627\\u0644\\u062b\\u0642\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u064f\\u062a\\u0639\\u0627\\u0645\\u0644\\u064a\\u0646, \\u0648\\u064a\\u062a\\u0645\\u062b\\u0644 \\u0627\\u0644\\u062f\\u0648\\u0631 \\u0641\\u064a:\"}', NULL, '2025-02-20 11:50:22', '2025-02-26 16:38:17'),
(300, 'writing_cvs_documents.element', '{\"title\":\"Mediation by facilitating the labor recruitment process\",\"title_ar\":\"\\u0627\\u0644\\u0648\\u0633\\u0627\\u0637\\u0629 \\u0628\\u062a\\u0633\\u0647\\u064a\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629\"}', NULL, '2025-02-20 11:50:40', '2025-02-26 16:38:43'),
(301, 'writing_cvs_documents.element', '{\"title\":\"Drafting, writing, reviewing and documenting employment contracts\",\"title_ar\":\"\\u0627\\u0644\\u0648\\u0633\\u0627\\u0637\\u0629 \\u0628\\u062a\\u0633\\u0647\\u064a\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629\"}', NULL, '2025-02-20 11:50:52', '2025-02-26 16:39:33'),
(302, 'pre_contract_qualification.element', '{\"title\":\"Rehabilitation, training, empowerment and mental health promotion\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0627\\u0644\\u062a\\u0645\\u0643\\u064a\\u0646 \\u0648\\u062a\\u0639\\u0632\\u064a\\u0632 \\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629\"}', NULL, '2025-02-26 15:12:10', '2025-02-26 15:12:10'),
