(304, 'pre_contract_qualification.element', '{\"title\":\"Providing rehabilitation, training, training and employment programmes\",\"title_ar\":\"\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u0627\\u0647\\u064a\\u0644\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0638\\u064a\\u0641\"}', NULL, '2025-02-26 15:12:55', '2025-02-26 15:12:55'),
(305, 'pre_contract_qualification.element', '{\"title\":\"Qualification courses and specialized workshops through specialized institutes to qualify workers\",\"title_ar\":\"\\u062f\\u0648\\u0631\\u0627\\u062a \\u062a\\u0623\\u0647\\u064a\\u0644\\u064a\\u0629 \\u0648\\u0648\\u0631\\u0634 \\u0639\\u0645\\u0644 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0645\\u0639\\u0627\\u0647\\u062f \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0644\\u064a\\u0646\"}', NULL, '2025-02-26 15:18:00', '2025-02-26 15:18:34'),
(306, 'pre_contract_qualification.element', '{\"title\":\"Connecting and building bridges between our partners and rehabilitation, training and employment centres\",\"title_ar\":\"\\u0631\\u0628\\u0637 \\u0648\\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062c\\u0633\\u0648\\u0631 \\u0628\\u064a\\u0646 \\u0634\\u0631\\u0643\\u0627\\u0626\\u0646\\u0627 \\u0648\\u0645\\u0631\\u0627\\u0643\\u0632 \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0638\\u064a\\u0641\"}', NULL, '2025-02-26 15:56:17', '2025-02-26 15:56:17'),
(307, 'pre_contract_qualification.element', '{\"title\":\"Connecting and building bridges between our partners and rehabilitation, training and employment centres\",\"title_ar\":\"\\u0631\\u0628\\u0637 \\u0648\\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062c\\u0633\\u0648\\u0631 \\u0628\\u064a\\u0646 \\u0634\\u0631\\u0643\\u0627\\u0626\\u0646\\u0627 \\u0648\\u0645\\u0631\\u0627\\u0643\\u0632 \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0638\\u064a\\u0641\"}', NULL, '2025-02-26 15:56:49', '2025-02-26 15:56:49'),
(308, 'pre_contract_qualification.element', '{\"title\":\"Proposing rehabilitation programs, identifying needs, and preparing and preparing rehabilitation programs\",\"title_ar\":\"\\u0627\\u0642\\u062a\\u0631\\u0627\\u062d \\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0648\\u062a\\u062d\\u062f\\u064a\\u062f \\u0627\\u0644\\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0648\\u0625\\u0639\\u062f\\u0627\\u062f \\u0648\\u0625\\u0639\\u062f\\u0627\\u062f \\u0627\\u0644\\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644\\u064a\\u0629\"}', NULL, '2025-02-26 15:57:22', '2025-02-26 15:57:22'),
(309, 'pre_contract_qualification.element', '{\"title\":\"Preparing a plan for recruitment, selection, training, and providing temporal and spatial service\",\"title_ar\":\"\\u0625\\u0639\\u062f\\u0627\\u062f \\u062e\\u0637\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0642\\u0637\\u0627\\u0628 \\u0648\\u0627\\u0644\\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u0648\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0632\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646\\u064a\\u0629\"}', NULL, '2025-02-26 15:57:54', '2025-02-26 15:57:54'),
(310, 'training_after_recruitment.element', '{\"title\":\"Re-introducing rehabilitation programmes, orientations and workshops for workers\",\"title_ar\":\"\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0648\\u062c\\u0647\\u0627\\u062a \\u0648\\u0648\\u0631\\u0634 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0644\\u0644\\u0639\\u0645\\u0627\\u0644\"}', NULL, '2025-02-26 16:02:39', '2025-02-26 16:02:39'),
(311, 'training_after_recruitment.element', '{\"title\":\"Providing a calm environment to help him understand Saudi culture\",\"title_ar\":\"\\u062a\\u0648\\u0641\\u064a\\u0631 \\u0628\\u064a\\u0626\\u0629 \\u0647\\u0627\\u062f\\u0626\\u0629 \\u0644\\u062a\\u0633\\u0627\\u0639\\u062f\\u0647 \\u0639\\u0644\\u0649 \\u0641\\u0647\\u0645 \\u0627\\u0644\\u062b\\u0642\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0633\\u0639\\u0648\\u062f\\u064a\\u0629\"}', NULL, '2025-02-26 16:03:33', '2025-02-26 16:03:44'),
