(328, 'labsincu.element', '{\"title\":\"We have a technical center and halls for examining professional and non-professional workers in the partner centers associated with us\",\"title_ar\":\"\\u0644\\u062f\\u064a\\u0646\\u0627 \\u0645\\u0631\\u0643\\u0632 \\u062a\\u0642\\u0646\\u064a \\u0648\\u0642\\u0627\\u0639\\u0627\\u062a \\u0644\\u0641\\u062d\\u0635 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0647\\u0646\\u064a\\u0629 \\u0648\\u0627\\u0644\\u063a\\u064a\\u0631 \\u0645\\u0647\\u0646\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0643\\u0632 \\u0627\\u0644\\u0634\\u0631\\u064a\\u0643\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0645\\u0639\\u0646\\u0627\"}', NULL, '2025-02-26 16:20:58', '2025-02-26 16:24:10'),
(329, 'labsincu.element', '{\"title\":\"We have provided a work team capable of analyzing and understanding our customers\\u2019 requirements in any field, and a special department has also been appointed for customer service around the clock\",\"title_ar\":\"\\u0642\\u062f\\u0645 \\u0625\\u0644\\u064a\\u0646\\u0627 \\u0641\\u0631\\u064a\\u0642 \\u0639\\u0645\\u0644 \\u0642\\u0627\\u062f\\u0631 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0644\\u064a\\u0644 \\u0648 \\u0641\\u0647\\u0645 \\u0645\\u062a\\u0637\\u0644\\u0628\\u0627\\u062a \\u0639\\u0645\\u0644\\u0627\\u0626\\u0646\\u0627 \\u0641\\u064a \\u0623\\u064a \\u0645\\u062c\\u0627\\u0644 \\u0648\\u062a\\u0645 \\u0627\\u064a\\u0636\\u0627 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0642\\u0633\\u0645 \\u062e\\u0627\\u0635 \\u0644\\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0639\\u0644\\u0649 \\u0645\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629\"}', NULL, '2025-02-26 16:24:39', '2025-02-26 16:24:39');
