(330, 'authentication_of_documents.element', '{\"title\":\"We are here to help with visa processing\",\"title_ar\":\"\\u0646\\u062d\\u0646 \\u0647\\u0646\\u0627 \\u0644\\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0641\\u064a \\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0634\\u0624\\u0648\\u0646 \\u0627\\u0644\\u062a\\u0651\\u064e\\u0623\\u0634\\u064a\\u0631\\u0627\\u062a\"}', NULL, '2025-02-26 16:29:15', '2025-02-26 16:29:15'),
(331, 'authentication_of_documents.element', '{\"title\":\"Our team will follow up on your visa from the beginning of the process to the end, making every effort Facilitating it and accelerating obtaining it without problems is what makes us the first choice In moving smoothly and easily from their country of residence to any other country\",\"title_ar\":\"\\u0633\\u064a\\u0639\\u0645\\u0644 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0639\\u0644\\u0649 \\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u062a\\u0623\\u0634\\u064a\\u0631\\u062a\\u0643 \\u0645\\u0646\\u0630 \\u0628\\u062f\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0651\\u064e\\u0629 \\u062d\\u062a\\u0651\\u064e\\u0649 \\u0646\\u0647\\u0627\\u064a\\u062a\\u0647\\u0627\\u060c \\u0628\\u0627\\u0630\\u0644\\u064a\\u0646 \\u0623\\u0642\\u0635\\u0649 \\u062c\\u0647\\u0648\\u062f\\u0647\\u0645  \\u062a\\u0633\\u0647\\u064a\\u0644\\u0647\\u0627 \\u0648\\u062a\\u0633\\u0631\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u064a\\u0647\\u0627 \\u062f\\u0648\\u0646 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0647\\u0630\\u0627 \\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644\\u0646\\u0627 \\u0627\\u0644\\u062e\\u064a\\u0627\\u0631 \\u0627\\u0644\\u0623\\u0648\\u0651\\u0644 \\u0641\\u064a \\u0627\\u0650\\u0646\\u062a\\u0642\\u0627\\u0644\\u0647\\u0645 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0648\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0645\\u0646 \\u0628\\u0644\\u062f \\u0625\\u0642\\u0627\\u0645\\u062a\\u0647\\u0645 \\u0644\\u0623\\u064a\\u0651 \\u0628\\u0644\\u062f \\u0622\\u062e\\u0631\"}', NULL, '2025-02-26 16:29:40', '2025-02-26 16:29:50'),
