(385, 'values_section.element', '{\"title\":\"Empowerment\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0645\\u0643\\u064a\\u0646\",\"subtitle\":\"We believe in the power of people to drive change\",\"subtitle_ar\":\"\\u0646\\u0624\\u0645\\u0646 \\u0628\\u062f\\u0648\\u0631 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0627\\u0646 \\u0641\\u064a \\u0635\\u0646\\u0627\\u0639\\u0629 \\u0627\\u0644\\u062a\\u063a\\u064a\\u064a\\u0631\"}', NULL, '2025-07-20 11:15:13', '2025-07-20 11:15:13'),
