(389, 'values_section.element', '{\"title\":\"Commitment\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645\",\"subtitle\":\"We place partner and client satisfaction at the core of our work\",\"subtitle_ar\":\"\\u0646\\u0636\\u0639 \\u0631\\u0636\\u0627 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u0621 \\u0648\\u0627\\u0644\\u062c\\u0647\\u0627\\u062a \\u0641\\u064a \\u0635\\u0645\\u064a\\u0645 \\u0623\\u0639\\u0645\\u0627\\u0644\\u0646\\u0627\"}', NULL, '2025-07-20 11:19:59', '2025-07-20 11:19:59'),
(390, 'whowe_serve.content', '{\"has_image\":\"1\",\"title\":\"Who We Serve\",\"title_ar\":\"\\u0645\\u0646 \\u0646\\u062e\\u062f\\u0645\\u061f\",\"sub_title\":\"The Human Resources Incubator serves a broad range of stakeholders, including\",\"sub_title_ar\":\"\\u062a\\u062e\\u062f\\u0645 \\u062d\\u0627\\u0636\\u0646\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0628\\u0634\\u0631\\u064a\\u0629 \\u0637\\u064a\\u0641\\u064b\\u0627 \\u0648\\u0627\\u0633\\u0639\\u064b\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u062c\\u0647\\u0627\\u062a\\u060c \\u062a\\u0634\\u0645\\u0644\",\"bottom\":\"We facilitate access to services through a unified platform with a modern, user-friendly interface and customized solutions tailored to each client\\u2019s needs\",\"bottom_ar\":\"\\u0646\\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u064a\\u0633\\u064a\\u0631 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0644\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a\\u060c \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u062d\\u0644\\u0648\\u0644 \\u0645\\u062e\\u0635\\u0635\\u0629 \\u062a\\u0644\\u0627\\u0626\\u0645 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0643\\u0644 \\u0641\\u0626\\u0629\\u060c \\u0639\\u0628\\u0631 \\u0645\\u0646\\u0635\\u0629 \\u0645\\u0648\\u062d\\u062f\\u0629\\u060c \\u0648\\u0648\\u0627\\u062c\\u0647\\u0629 \\u062a\\u0642\\u0646\\u064a\\u0629 \\u062d\\u062f\\u064a\\u062b\\u0629.\",\"image\":\"687cd867971951753012327.png\"}', NULL, '2025-07-20 11:52:07', '2025-07-20 12:06:21'),
