(468, 'training_program_features.element', '{\"has_image\":\"1\",\"title\":\"Pre- and post-assessments to measure training impact\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645\\u0627\\u062a \\u0627\\u0644\\u0633\\u0627\\u0628\\u0642\\u0629 \\u0648\\u0627\\u0644\\u0644\\u0627\\u062d\\u0642\\u0629 \\u0644\\u0642\\u064a\\u0627\\u0633 \\u062a\\u0623\\u062b\\u064a\\u0631 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628\",\"image\":\"6888b99dedf081753790877.png\"}', NULL, '2025-07-29 12:07:57', '2025-07-29 12:07:58'),
(469, 'training_program_features.element', '{\"has_image\":\"1\",\"title\":\"Certified digital training certificates.\",\"title_ar\":\"\\u0634\\u0647\\u0627\\u062f\\u0627\\u062a \\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0631\\u0642\\u0645\\u064a\\u0629 \\u0645\\u0639\\u062a\\u0645\\u062f\\u0629.\",\"image\":\"6888b9b1eea571753790897.png\"}', NULL, '2025-07-29 12:08:17', '2025-07-29 12:08:18'),
(470, 'training_program_features.element', '{\"has_image\":\"1\",\"title\":\"Learner performance tracking through a Learning Management System (LMS).\",\"title_ar\":\"\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0623\\u062f\\u0627\\u0621 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0645 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0646\\u0638\\u0627\\u0645 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0644\\u0645 (LMS).\",\"image\":\"6888b9c44ec4a1753790916.png\"}', NULL, '2025-07-29 12:08:36', '2025-07-29 12:08:36'),
(471, 'training_program_features.element', '{\"has_image\":\"1\",\"title\":\"Integration between training programs and actual employment opportunities\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0628\\u064a\\u0646 \\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0641\\u0631\\u0635 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u0629\",\"image\":\"6888b9d55d4c71753790933.png\"}', NULL, '2025-07-29 12:08:53', '2025-07-29 12:08:53');
