INSERT INTO `jobs` (`id`, `user_id`, `job_category_id`, `country_id`, `district_id`, `status`, `featured`, `company_id`, `title`, `description`, `title_ar`, `description_ar`, `deadline`, `qualification`, `jobtype`, `salarytype`, `salarycurrency`, `salaryrange`, `experience`, `level`, `vacancies`, `skill`, `location`, `created_at`, `updated_at`) VALUES
(7, 56, 87, 2, NULL, 1, 0, NULL, 'مطلوب مسوقين بالعمولة', '<h3 style=\"direction: rtl;\">مطلوب لشركة مرموقة بمجال التكنولوجيا:</h3>\r\n<p style=\"direction: rtl;\"><strong>دعوة&nbsp; للانضمام لفريق عمل تسويقي احترافي&nbsp;</strong></p>\r\n<p style=\"direction: rtl;\"><strong>في&nbsp; اي زمان او مكان فرصة للعمل عن بعد ويتمثل في:&nbsp;</strong></p>\r\n<p style=\"direction: rtl;\"><strong>١- تسويق خدمات مختلفة لشركات ومؤسسات في مجال الاستشارات والتوظيف والخدمات التقنية والتسويق الرقعي وتنظيم الفعاليات والعلاقات العامة والاعلام والنشر&nbsp;&nbsp;</strong></p>\r\n<p style=\"direction: rtl;\"><strong>٢- التصميم .. كتابة المحتوى .. ادارة مواقع التواصل الاجتماعي .. جمع المعلومات&nbsp; &nbsp;</strong></p>\r\n<p style=\"direction: rtl;\"><strong>&nbsp;لايتطلب التفرغ .. الدخل المتوقع للفرد في التسويق من ٣٠٠٠ الاف ريال إلى ٦٠٠٠ الاف ريال تسويق الخدمات داخل السعودية فقط نظير عمولة تبدأ من 10 ٪؜&nbsp;</strong></p>\r\n<p style=\"direction: rtl;\"><strong>يعتمد العمل على جميع مواقع التواصل الاجتماعي ونشر الخدمات.&nbsp;</strong></p>\r\n<p>&nbsp;</p>', NULL, NULL, '2022-12-12', 4, 5, 3, 5, 7, 1, 4, '50', NULL, 'الرياض', '2020-11-30 12:26:00', '2021-03-04 12:09:32'),
(8, 56, 87, 2, 3, 1, 0, NULL, 'مطلوب متخصصة بالتسويق الرقمي لادارة التسويق الرقمي بشركة مرموقة', '<h1 style=\"direction: rtl; box-sizing: border-box; margin: 0px 0px 10px; font-family: \'Droid Arabic Kufi\', sans-serif; color: #656f77; font-size: 14px; line-height: 25px; text-align: justify; background-color: #ffffff;\"><span style=\"font-size: 14pt; color: #000000;\"><strong>مطلوب للعمل بشركة مرموقة بالرياض:</strong></span></h1>\r\n<p style=\"direction: rtl; box-sizing: border-box; margin: 0px 0px 10px; font-family: \'Droid Arabic Kufi\', sans-serif; color: #656f77; font-size: 14px; line-height: 25px; text-align: justify; background-color: #ffffff;\"><span style=\"font-size: 14pt; color: #000000;\"><strong>متخصصة بالتسويق الرقمي للقيام بالمهام التالية:</strong></span></p>\r\n<p class=\"MsoBodyText3\" dir=\"RTL\" style=\"box-sizing: border-box; margin: 0px 0.5in 10px 0px; font-family: \'Droid Arabic Kufi\', sans-serif; color: #656f77; font-size: 14px; line-height: 25px; text-align: justify; background-color: #ffffff; text-indent: -0.25in;\"><span style=\"font-size: 12pt; color: #000000;\"><strong><span lang=\"X-NONE\" style=\"box-sizing: border-box; font-family: Symbol; letter-spacing: 0px;\"><span style=\"box-sizing: border-box; font-family: \'Droid Arabic Kufi\', sans-serif; letter-spacing: 0px;\">&middot;<span style=\"box-sizing: border-box; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; letter-spacing: 0px;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></span><span lang=\"AR-SA\" style=\"box-sizing: border-box; font-family: \'AL-Mohanad Bold\'; letter-spacing: 0px;\">بناء الهيكل التنظيمي والوصف الوظيفي للفريق</span></strong></span></p>\r\n<p class=\"MsoBodyText3\" dir=\"RTL\" style=\"box-sizing: border-box; margin: 0px 0.5in 10px 0px; font-family: \'Droid Arabic Kufi\', sans-serif; color: #656f77; font-size: 14px; line-height: 25px; text-align: justify; background-color: #ffffff; text-indent: -0.25in;\"><span style=\"font-size: 12pt; color: #000000;\"><strong><span lang=\"X-NONE\" style=\"box-sizing: border-box; font-family: Symbol; letter-spacing: 0px;\"><span style=\"box-sizing: border-box; font-family: \'Droid Arabic Kufi\', sans-serif; letter-spacing: 0px;\">&middot;<span style=\"box-sizing: border-box; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; letter-spacing: 0px;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></span><span lang=\"AR-SA\" style=\"box-sizing: border-box; font-family: \'AL-Mohanad Bold\'; letter-spacing: 0px;\">عمل ال&nbsp;</span><span dir=\"LTR\" style=\"box-sizing: border-box; letter-spacing: 0px;\">SEO</span><span lang=\"AR-SA\" style=\"box-sizing: border-box; font-family: \'AL-Mohanad Bold\'; letter-spacing: 0px;\">&nbsp;للحسابات</span></strong></span></p>\r\n<p class=\"MsoBodyText3\" dir=\"RTL\" style=\"box-sizing: border-box; margin: 0px 0.5in 10px 0px; font-family: \'Droid Arabic Kufi\', sans-serif; color: #656f77; font-size: 14px; line-height: 25px; text-align: justify; background-color: #ffffff; text-indent: -0.25in;\"><span style=\"font-size: 12pt; color: #000000;\"><strong><span lang=\"X-NONE\" style=\"box-sizing: border-box; font-family: Symbol; letter-spacing: 0px;\"><span style=\"box-sizing: border-box; font-family: \'Droid Arabic Kufi\', sans-serif; letter-spacing: 0px;\">&middot;<span style=\"box-sizing: border-box; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; letter-spacing: 0px;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></span><span lang=\"AR-SA\" style=\"box-sizing: border-box; font-family: \'AL-Mohanad Bold\'; letter-spacing: 0px;\">بناء قاعدة بيانات لجميع الانشطة للعاملين بالقطاع</span></strong></span></p>\r\n<p class=\"MsoBodyTe