INSERT INTO `sectors` (`id`, `title`, `title_ar`, `description`, `description_ar`, `image`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(9, 'Environmental and Support Services Sector', 'قطاع البيئة والخدمات المساندة', 'Providing skilled labor for cleaning services, landscape maintenance, pest control, and environmental supervision', 'توفير كوادر مؤهلة في أعمال النظافة، صيانة المسطحات الخضراء، مكافحة الآفات، والإشراف البيئي', '67ce7a4dc85b41741584973.png', 1, 1, '2025-03-04 10:04:34', '2025-07-21 09:15:37'),
(10, 'Telecommunications and Service Centers', 'قطاع الاتصالات ومراكز الخدمة', 'Operating cloud-based contact centers, IVR systems, technical support services, and AI-powered customer experience enhancements', 'تشغيل مراكز الاتصال، الرد الآلي، خدمات الدعم التقني، وتحسين تجربة العميل عبر الحلول الذكية', '67ce7a466a03b1741584966.png', 1, 1, '2025-03-04 10:05:38', '2025-07-21 09:14:58'),
(11, 'Higher Education and Training Sector', 'قطاع التعليم العالي والتدريب', 'Supporting institutes and universities with educational and administrative staff, and offering internship and student training solutions', 'دعم المعاهد والجامعات بالكفاءات التعليمية والإدارية، وتوفير حلول لتدريب الطلاب والمتدربين', '67ce7a3d3b3811741584957.png', 1, 1, '2025-03-04 10:06:54', '2025-07-21 09:14:06'),
(12, 'Transport and Logistics Sector', 'قطاع النقل والخدمات اللوجستية', 'Providing drivers, forklift operators, loaders, warehouse staff, along with resource scheduling and compliance training', 'توفير السائقين، ومشغلي الرافعات، وعمال التحميل والتخزين، مع خدمات جدولة الموارد وتدريبهم على الالتزام', '67ce7a34e96771741584948.png', 1, 1, '2025-03-04 10:08:01', '2025-07-21 09:13:16'),
(13, 'Healthcare Sector', 'القطاع الصحي', 'Supplying administrative and technical support staff for healthcare facilities, as well as nursing, patient care, and safety training services', 'توفير الدعم الإداري والفني للمرافق الصحية، وخدمات التمريض والمرافقة والتدريب على السلامة المهنية', '67ce7a1e0da171741584926.png', 1, 1, '2025-03-04 10:09:06', '2025-07-21 09:12:01'),
(14, 'Construction and Contracting Sector', 'قطاع البناء والتشييد', 'Providing skilled and temporary labor in construction, maintenance, cleaning, safety, and on-site management', 'توفير عمالة ماهرة ومؤقتة في الإنشاءات، الصيانة، النظافة، السلامة، وإدارة مواقع العمل الميداني', '67ce7aae6aebd1741585070.png', 1, 1, '2025-03-04 10:09:52', '2025-07-21 09:11:13'),
(15, 'Restaurants and Cafes Sector', 'قطاع المطاعم والكافيهات', 'Recruiting and training chefs, service staff, delivery personnel, with a focus on behavioral and operational excellence', 'تأهيل وتشغيل الطهاة، مقدمي الخدمة، موظفي التوصيل، وخدمات التدريب السلوكي والتشغيلي', '67ce79ec684c71741584876.png', 1, 1, '2025-03-04 10:11:05', '2025-07-21 09:09:53'),
(16, 'Hospitality, Tourism, and Hotel Sector', 'قطاع الضيافة والسياحة والفندقة', 'Supplying specialized staff for hotels, resorts, front desk operations, and guest services, with dedicated training programs.', 'توفير الكوادر المتخصصة في الفنادق، المنتجعات، مراكز الاستقبال، وخدمة الضيوف، مع برامج تدريب مخصصة', '67ce79f53b4f01741584885.png', 1, 1, '2025-03-04 10:12:24', '2025-07-21 09:08:50'),
(17, 'Agricultural and Food Sector', 'القطاع الزراعي والغذائي', 'Providing seasonal and skilled labor for harvesting, packing, food processing, and rural hospitality—alongside localization and vocational training support', 'توفير عمالة موسمية ومؤهلة في الحصاد، التعبئة، التغليف، والضيافة الريفية، مع دعم التوطين والتدريب المهني', '67ce7a014b6691741584897.png', 1, 1, '2025-03-04 10:13:12', '2025-07-21 09:06:56'),
(18, 'Industrial and Mining Sector', 'القطاع الصناعي والتعديني', 'Supplying trained technical and professional labor, and offering outsourcing and HR support services for operational efficiency', 'توفير عمالة فنية ومهنية مدربة، وتقديم حلول تعهيد وتشغيل مراكز الدعم الفني وخدمات الموارد البشرية', '67ce7a0b45c4b1741584907.png', 1, 1, '2025-03-04 10:14:11', '2025-07-21 09:05:15'),
(19, 'Commercial and Service Sector', 'القطاع التجاري والخدمي', 'Supporting SMEs and large enterprises in recruitment, operations, workforce development, and enhancing customer service quality', 'دعم المنشآت الصغيرة والمتوسطة والمؤسسات الكبرى في التوظيف، والتشغيل، وتطوير الكوادر، ورفع جودة خدمة العملاء', '67ce7a155e87e1741584917.png', 1, 1, '2025-03-04 10:14:47', '2025-07-21 09:04:40');
